// ChatSidebar.js
import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatSidebar.css";

const ChatSidebar = ({ onSelectConversation }) => {
  const [conversations, setConversations] = useState([]);
  const [searchUsername, setSearchUsername] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState(null);

  const loggedInUser = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    if (!loggedInUser) return;

    axios
      .get("/api/conversations", {
        headers: { Authorization: `Bearer ${loggedInUser.token}` },
      })
      .then((res) => {
        setConversations(res.data);
        console.log("Fetched conversations:", res.data);
      })
      .catch((err) => {
        console.error("Error fetching conversations:", err);
        setConversations([]); // ensure array
      });
  }, [loggedInUser]);

  const handleSearch = () => {
    if (!searchUsername.trim()) return;

    axios
      .get(`/api/profile/search?username=${searchUsername}`, {
        headers: { Authorization: `Bearer ${loggedInUser.token}` },
      })
      .then((res) => {
        const profiles = res.data;
        console.log(`# of users found: ${profiles.length}`);
        setSearchResults(profiles);
      })
      .catch((err) => {
        console.error("Error searching users:", err);
        setSearchResults([]);
      });
  };

  const handleSelectUser = async (user) => {
    setSelectedUserId(user._id);

    try {
      const res = await axios.post(
        "/api/conversations",
        { receiverId: user._id },
        {
          headers: { Authorization: `Bearer ${loggedInUser.token}` },
        }
      );

      const conversation = res.data;
      console.log("Conversation created or found:", conversation);
      onSelectConversation(conversation);
    } catch (err) {
      console.error("Error creating conversation:", err);
    }
  };

  return (
    <div className="chat-sidebar">
      <h4>Messages</h4>

      <input
        type="text"
        placeholder="Search user..."
        value={searchUsername}
        onChange={(e) => setSearchUsername(e.target.value)}
      />
      <button className="search-btn" onClick={handleSearch}>
        Search
      </button>

      {searchResults.map((profile) => (
        <div
          key={profile.userId._id}
          className={`search-result ${
            selectedUserId === profile.userId._id ? "active" : ""
          }`}
          onClick={() => handleSelectUser(profile.userId)}
        >
          {profile.userId.username}
        </div>
      ))}

      {Array.isArray(conversations) && conversations.length === 0 && (
        <i>No conversations found.</i>
      )}

      {Array.isArray(conversations) &&
        conversations.map((c) => {
          const other = c.participantUsernames?.find(
            (u) => u !== loggedInUser.username
          );
          return (
            <div
              key={c._id}
              className={`conversation-item ${
                selectedUserId === c._id ? "active" : ""
              }`}
              onClick={() => onSelectConversation(c)}
            >
              {other}
            </div>
          );
        })}
    </div>
  );
};

export default ChatSidebar;
